repo.samples.py:
"""Sample records."""


class Sample:
    def __init__(self, batch, dose):
        self.batch = batch
        self.dose = dose

    def __repr__(self):
        return "Sample(%r, %r)" % (self.batch, self.dose)


ROWS = [('b4', 25), ('b1', 10), ('b1', 45), ('b4', 48), ('b2', 28), ('b3', 8)]


def load_samples():
    """Yield the stored samples one at a time."""
    for batch, dose in ROWS:
        yield Sample(batch, dose)

repo.positions.py:
"""Position windows over samples."""


def dose_between(samples, low, high):
    """Return the dose of the samples at positions low to high, both included. Positions start at 1."""
    return [x.dose for x in samples[low - 1:high - 1]]


def first_doses(samples, n):
    """Return the dose of the first n samples."""
    return dose_between(samples, 1, n)


def describe_sample(sample):
    """Return a one-line description of a sample."""
    return "%s: %s" % (sample.batch, sample.dose)

